import {listLibrary,getLibrary,saveLibrary,libraryId,exportLibrary,importLibrary,watchLibrary} from './studio-library.mjs';
export function mountSavedLibrary({kind,label,anchor,picker,getProject,portable,load,message,download,beforeSave,afterSave,getName}){
 const panel=document.createElement('details');panel.className='saved-library';panel.dataset.library=kind;
 const legend=document.createElement('summary');legend.textContent=label+' đã lưu · mở / lưu / sao lưu';
 if(!document.getElementById('savedLibraryStyle')){const style=document.createElement('style');style.id='savedLibraryStyle';style.textContent='.saved-library{border:1px solid #41516a;border-radius:8px;padding:12px;margin:12px 0;min-width:0;overflow-wrap:anywhere}.saved-library summary{cursor:pointer;color:#d3ed92;padding:5px 0}.saved-library[open] summary{margin-bottom:12px}.saved-library select,.saved-library button{width:100%;box-sizing:border-box;margin-bottom:8px}.saved-library p{font-size:12px;line-height:1.5;opacity:.8}';document.head.append(style)}
 const select=document.createElement('select');select.setAttribute('aria-label',label+' đã lưu');
 const save=document.createElement('button'),copy=document.createElement('button'),open=document.createElement('button'),backup=document.createElement('button'),restore=document.createElement('button'),file=document.createElement('input'),info=document.createElement('p');
 save.textContent='Lưu vào thư viện';copy.textContent='Lưu thành bản mới';open.textContent='Mở bản đã chọn';backup.textContent='Sao lưu toàn bộ thư viện';restore.textContent='Nhập bản sao thư viện';file.type='file';file.accept='.json';file.hidden=true;
 info.textContent='Lưu trên trình duyệt / thiết bị này, gồm ảnh và điểm neo. Không tự đồng bộ sang máy khác. Hãy tải bản sao trước khi xóa dữ liệu trình duyệt.';
 panel.append(legend,select,open,save,copy,backup,restore,file,info);anchor.after(panel);
 const safe=fn=>async(...args)=>{try{await fn(...args)}catch(e){message('Lỗi thư viện: '+e.message)}};
 async function refresh(){const rows=await listLibrary(kind),old=select.value;select.replaceChildren(new Option('— Chọn bản đã lưu —',''),...rows.map(r=>new Option(getName?.(r.data)||r.name,r.id)));select.value=rows.some(r=>r.id===old)?old:'';open.disabled=!select.value;
  if(picker){const value=picker.value;picker.querySelector('optgroup[data-saved-library]')?.remove();const group=document.createElement('optgroup');group.label='Đã lưu của bạn';group.dataset.savedLibrary=kind;group.append(...rows.map(r=>new Option(getName?.(r.data)||r.name,'saved:'+r.id)));picker.append(group);picker.value=value}
 }
 let saving=false;
 async function saveCurrent({copy=false}={}){if(saving)throw Error('Đang lưu thư viện, chờ hoàn tất');saving=true;let p,previous,committed=false;try{await beforeSave?.();p=getProject();if(!p)throw Error('Chờ project tải xong');previous=p.studioLibraryId;const id=libraryId(p,{copy}),data=await portable();if(getProject()!==p)throw Error('Thiết kế vừa thay đổi, hãy lưu lại');data.studioLibraryId=id;await saveLibrary(kind,id,String(data.name||data.rig||data.id||label).slice(0,200),data);committed=true;await afterSave?.(data);await refresh();select.value=id;open.disabled=false;message('Đã lưu '+label.toLowerCase()+' vào thư viện, gồm ảnh và các cấu hình.');return data}catch(e){if(p&&!committed){if(previous)p.studioLibraryId=previous;else delete p.studioLibraryId}throw e}finally{saving=false}}
 async function openId(id){const r=await getLibrary(kind,id);if(!r)throw Error('Không tìm thấy bản lưu');await load(structuredClone(r.data));select.value=id;message('Đã mở '+r.name+' từ thư viện.')}
 save.onclick=safe(()=>saveCurrent());copy.onclick=safe(()=>saveCurrent({copy:true}));open.onclick=safe(()=>openId(select.value));select.onchange=()=>open.disabled=!select.value;
 if(picker)picker.addEventListener('change',e=>{if(!picker.value.startsWith('saved:'))return;e.stopImmediatePropagation();safe(()=>openId(picker.value.slice(6)))()},{capture:true});
 backup.onclick=safe(async()=>download('darkin-thu-vien.studio-library.json',JSON.stringify(await exportLibrary())));restore.onclick=()=>file.click();file.onchange=safe(async()=>{try{const f=file.files[0];if(!f)return;if(f.size>200*1024*1024)throw Error('Bản sao tối đa 200 MB');const n=await importLibrary(JSON.parse(await f.text()));await refresh();message('Đã nhập '+n+' bản lưu. Dữ liệu trùng ID được cập nhật; các mục khác giữ nguyên.')}finally{file.value=''}});
 async function saveAndDownload(filename){await beforeSave?.();let data,error;try{data=await saveCurrent()}catch(e){error=e;data=await portable()}download(typeof filename==='function'?filename(data):filename,JSON.stringify(data,null,2));message(error?'Đã tải bản sao project. Chưa lưu đủ vào thư viện: '+error.message:'Đã lưu '+label.toLowerCase()+' vào thư viện và tải bản sao kèm ảnh.');return data}
 watchLibrary(safe(refresh));safe(refresh)();return {save:saveCurrent,saveAndDownload,refresh,open:openId,panel};
}
